 for(const row of devices){assert.deepEqual(Object.keys(row).sort(),['createdAt','fingerprintPresent','id','locationSha256','userAgentSha256','userId']);assert(Number.isSafeInteger(row.id)&&row.id>0);assert(Number.isSafeInteger(row.userId)&&row.userId>0);assert(Number.isFinite(Date.parse(row.createdAt)));assert.equal(typeof row.fingerprintPresent,'boolean');for(const key of ['userAgentSha256','locationSha256'])assert.match(row[key]??'',/^[a-f0-9]{64}$/u);}
