export async function nativeEmailBusinessStage(s,{namespace,inputs}){admit(s,namespace);assertEmailProducer(inputs?.emailSetup,s,namespace);if(inputs.emailSetup.retainedInitial)assertRetainedInitialEmail(inputs.emailSetup.retainedInitial,inputs.emailSetup,namespace,s.tenantId);const {ensureNativeAgent}=await import('./simulation-native-agent.mjs'),agent=await ensureNativeAgent(s),actor=await agent.verify();await agent.page.setViewportSize({width:1440,height:1000});const output=join(s.output,'email-business');await mkdir(output,{mode:0o700});if(!inputs.emailSetup.retainedInitial){const ruby=await native(s,namespace);const recipient=assertInitialMailRecipient(await ruby('native-failure-fixture.rb',{action:'recipient-state',originalRecipient:'customer@alpha.invalid'}));await record(output,'recipient-before-initial',recipient);}const result=await runFreshEmailVertical({...s,nativePage:agent.page,nativeActorId:actor.id,verifyNativeActor:agent.verify,mailEffects:await emailEffects(s,namespace,inputs.emailSetup),output,runId:namespace,fixtures:{email:inputs.emailSetup}}),email={...result.fixtures,evidenceMode:'simulated',namespace,tenantId:s.tenantId,ownership:inputs.emailSetup.ownership,startedAt:inputs.emailSetup.startedAt,nativeActorId:actor.id,effectBudget:inputs.emailSetup.effectBudget,...(inputs.emailSetup.retainedMailBaseline?{retainedMailBaseline:inputs.emailSetup.retainedMailBaseline}:{})},nativeRows=await observeEmailBusiness(s,agent,email,result.results);return{...email,results:mergeNativeBusinessRows(result.results,nativeRows)};}
export async function completeEmailFailureObservation({observe,merge,fixture,cleanup}){
 let rows=fixture.results,observationError;try{const nativeRows=await observe();if(nativeRows)rows=merge(nativeRows);}catch(error){observationError=error;}
 const settled={...fixture,results:rows};
 if(observationError||rows.some(row=>row.result==='failed'))try{settled.stageLocalTeardown=await cleanup(settled);}catch(cleanupError){if(observationError)throw new AggregateError([observationError,cleanupError],'Email UI observation and scoped cleanup failed');throw cleanupError;}
 if(observationError)throw observationError;return settled;
}
export async function nativeEmailFailureStage(s,{namespace,inputs}){
 admit(s,namespace);const email=assertEmailProducer(inputs?.email,s,namespace),{ensureNativeAgent}=await import('./simulation-native-agent.mjs'),agent=await ensureNativeAgent(s);const actor=await agent.verify();if(email.retainedBounce){if(email.retainedBounce.kind!=='reconciled-native-bounce')assert.equal(email.retainedBounce.namespace,'fresh399-8117-v5-q06m');if(email.nativeActorId!==undefined)assert.equal(actor.id,email.nativeActorId);}else assert.equal(actor.id,email.nativeActorId);
 const output=join(s.output,'email-failure');await mkdir(output,{mode:0o700});const result=await runFreshNativeMailFailureBounce({...s,nativePage:agent.page,nativeActorId:agent.actorId,mailEffects:email.retainedBounce&&email.retainedBounce.kind!=='reconciled-native-bounce'?undefined:await emailEffects(s,namespace,email),output,runId:namespace,fixtures:{email,startedAt:email.startedAt,retainedBounce:email.retainedBounce}});
 const fixture={evidenceMode:'simulated',namespace,tenantId:s.tenantId,email:{...email,...(result.effectReceipt?{effectReceipt:result.effectReceipt}:{})},faultNamespace:namespace,terminal:true,...(result.recipientRecovery?{recipientRecovery:result.recipientRecovery}:{}),results:result.results};
 // The runner stops on an unsettled failed row before its teardown stage. Contain
 // the already-settled mail effects and restore the exact recipient preimage here.
 return completeEmailFailureObservation({observe:()=>observeEmailFailure(s,agent,email,result.failureObservation,result.results),merge:nativeRows=>mergeNativeBusinessRows(result.results,nativeRows),fixture,cleanup:settled=>nativeEmailTeardownStage(s,{namespace,inputs:{emailFailure:settled}})});
}
export async function nativeEmailTeardownStage(s,{namespace,inputs,config={}}){admit(s,namespace);const f=assertEmailProducer(inputs?.emailFailure,s,namespace);assert(f.terminal);const email=assertEmailProducer(f.email,s,namespace);if(f.stageLocalTeardown){const settled=f.stageLocalTeardown,persisted=JSON.parse(await readFile(join(s.output,'email-teardown','result.json'),'utf8'));assert.deepEqual(persisted,settled);assert.equal(s.capabilities.nativeEmailAuthentication?.requiresReconciliation,false);assert.equal(settled.namespace,namespace);assert.equal(settled.smtpRestored,true);assert.equal(settled.recipientRestored,!email.retainedBounce);return settled;}if(!email.retainedBounce||email.retainedBounce.kind==='reconciled-native-bounce'){const effects=await emailEffects(s,namespace,email);await effects.before('teardown');}const output=join(s.output,'email-teardown');await mkdir(output,{mode:0o700});const ruby=await native(s,namespace);assert.equal((await ruby('native-failure-fixture.rb',{action:'preflight'})).pendingEmailJobs,0,'Native mail jobs must drain before restoration');const smtp=await sink(s);assert.equal(smtp.container.Id,email.ownership.sinkId);const original=email.ownership.smtpConfig;assert.equal(sha(JSON.stringify(original)),email.ownership.smtpConfigSha256);const current=JSON.parse(await smtp.read('config.json').then(b=>b.toString('utf8')));const faults=assertOwnedFaultRestoration(current,original,namespace);const journal=(await smtp.read('journal.jsonl').then(b=>b.toString('utf8'))).split('\n').filter(Boolean).map(JSON.parse);for(const f of faults)assert.equal(journal.filter(j=>j.faultId===f.id).length,1,'Every armed rejection must be terminal exactly once');const channelOwnerNamespace=email.channel.ownerNamespace??config.channelOwnerNamespace??namespace;assert.match(channelOwnerNamespace,/^[A-Za-z0-9-]{1,60}$/);await record(output,'restore-intent',{namespace,channelOwnerNamespace,currentConfig:current,originalConfig:original,channel:email.channel,ownedJobsDrained:true,uncertainOutcomesReconciled:true});await smtp.replaceConfig(current,original,'restore-'+namespace);await s.run('docker',['restart',smtp.container.Id]);const deadline=Date.now()+30000;while(true){const c=JSON.parse(await s.run('docker',['inspect',smtp.container.Id]))[0];if(c.State.Health?.Status==='healthy')break;assert(Date.now()<deadline,'Restored sink not healthy');await new Promise(r=>setTimeout(r,500));}assert.equal(await containerFileSha256(s.run,smtp.container.Id,'/run/wasalx-simulation/config.json'),sha(JSON.stringify(original)),'Restarted sink did not load the restored configuration');assert.deepEqual(JSON.parse(await smtp.read('config.json').then(b=>b.toString('utf8'))),original);assert.equal((await ruby('native-failure-fixture.rb',{action:'preflight'})).pendingEmailJobs,0);if(s.capabilities.nativeEmailAuthentication)await s.capabilities.nativeEmailAuthentication.contain();const channel=await ruby('channel-fixture.rb',{action:'restore',ownerRunId:channelOwnerNamespace,...email.channel,ownedJobsDrained:true,uncertainOutcomesReconciled:true});assert(channel.restored&&!channel.active);const recovery=f.recipientRecovery;let recipientRestored=false;
 if(!email.retainedBounce){assert(recovery?.before?.recipientMailState&&recovery?.after?.recipientMailState&&recovery?.bounceProofSha256,'Exact pre-bounce recipient state unavailable; scoped synthetic reinitialization requires separate review');const intent={state:'OUTCOME_UNKNOWN',namespace,recipient:'customer@alpha.invalid',preBounce:recovery.before,postBounce:recovery.after,bounceProofSha256:recovery.bounceProofSha256,ownedJobsDrained:true,uncertainOutcomesReconciled:true};await record(output,'recipient-restore-intent',intent);const recipientRestore=await ruby('native-failure-fixture.rb',{action:'recipient-mail-restore',originalRecipient:intent.recipient,preBounce:intent.preBounce,postBounce:intent.postBounce,bounceProofSha256:intent.bounceProofSha256,restoreIntentSha256:sha(JSON.stringify(intent,null,2)),ownedJobsDrained:true,uncertainOutcomesReconciled:true});assert.equal(recipientRestore.restored,true);assert.deepEqual(recipientRestore.recipient.recipientMailState,recovery.before.recipientMailState);await record(output,'recipient-restored',recipientRestore);recipientRestored=true;}
 else{assert.equal(recovery,undefined,'Retained bounce cannot acquire a fresh recipient preimage');await record(output,'recipient-not-restored',{namespace,sourceNamespace:email.retainedBounce.namespace,reason:'retained bounce has no exact pre-bounce recipient snapshot; preserve historical state'});}
 await record(output,'result',{evidenceMode:'simulated',namespace,smtpRestored:true,channel,routingRetained:true,recipientRestored});return{evidenceMode:'simulated',namespace,smtpRestored:true,channel,routingRetained:true,recipientRestored};}

export async function routingFiveStage(...args){return withOwnerEvidence(args[0],()=>routingFiveStageOperation(...args));}
async function routingFiveStageOperation(s,{namespace,inputs}) {
 admit(s,namespace);
 const group=inputs?.group;
 assert.equal(group?.evidenceMode,'simulated');
 assert.equal(group.tenantId,s.tenantId);
 assert.equal(group.namespace,namespace);
 assert(group.connectionId&&group.groupRef,'Current group producer required');
 const email=assertEmailProducer(inputs?.email,s,namespace);
 const output=join(s.output,'routing-five');
 await mkdir(output,{mode:0o700});
 const result=await runFreshRoutingFiveCases({...s,output,runId:namespace,fixtures:{group}});
 const {ensureNativeAgent}=await import('./simulation-native-agent.mjs'),agent=await ensureNativeAgent(s),actor=await agent.verify(),ownerRows=result.rows.map(row=>({testId:row.testId,result:row.result,startedAt:row.startedAt,finishedAt:row.finishedAt,contextId:'tenant_owner-en-desktop',proof:row})),nativeSourceRows=result.rows.filter(row=>row.testId!==routingSupportScopeId),targetGroups=[...new Map(nativeSourceRows.map(row=>[String(row.nativeTargets.group.id),row.nativeTargets.group])).values()];assert.equal(targetGroups.length,1);const targetGroup=targetGroups[0],agentEmail=s.model.services['zammad-runtime-bootstrap'].environment.WASALX_ZAMMAD_AGENT_EMAIL;assert(agentEmail);
 const ruby=await native(s,namespace),setupIntent={state:'OUTCOME_UNKNOWN',action:'routing-visibility-setup',agentId:actor.id,targetGroupId:targetGroup.id,targetGroupName:targetGroup.name};await record(output,'routing-visibility-setup-intent',setupIntent);const visibility=assertRoutingVisibilityReceipt(await ruby('channel-fixture.rb',{...setupIntent,action:'routing-visibility-setup',agentEmail}),{namespace,agentId:actor.id,targetGroupId:targetGroup.id});await record(output,'routing-visibility-setup-receipt',visibility);
 let nativeRows,observationError;try{nativeRows=await observeRoutingTargets(s,agent,email,nativeSourceRows);}catch(error){observationError=error;}
 let restorationError;try{await record(output,'routing-visibility-restore-intent',{state:'OUTCOME_UNKNOWN',ownerRunId:visibility.ownerRunId,agentId:visibility.agentId,targetGroupId:visibility.targetGroupId,controlGroupId:visibility.controlGroupId,originalAccessMap:visibility.originalAccessMap,observationSettled:true});const restored=assertRoutingVisibilityRestored(await ruby('channel-fixture.rb',{action:'routing-visibility-restore',ownerRunId:visibility.ownerRunId,agentId:visibility.agentId,targetGroupId:visibility.targetGroupId,controlGroupId:visibility.controlGroupId,originalAccessMap:visibility.originalAccessMap,observationSettled:true}),visibility);await record(output,'routing-visibility-restored',restored);}catch(error){restorationError=error;await record(output,'routing-visibility-configuration-held',{ownerRunId:visibility.ownerRunId,agentId:visibility.agentId,targetGroupId:visibility.targetGroupId,controlGroupId:visibility.controlGroupId});}
 if(restorationError)throw new AggregateError([...(observationError?[observationError]:[]),restorationError],'Native routing visibility fixture not restored');if(observationError)throw observationError;
 return {...result,evidenceMode:'simulated',namespace,tenantId:s.tenantId,results:[...ownerRows,...nativeRows]};
}

export async function adoptRetainedBounceEmailStage(s,{namespace,inputs}){
 admit(s,namespace);const email=assertEmailProducer(inputs?.emailSetup,s,namespace);assert.equal(email.retainedBounce?.kind,'reconciled-native-bounce');assert.equal(email.retainedBounce.adoptedNamespace,namespace);
 await s.checkpoint({phase:'retained-bounce-email-admitted',namespace,sourceNamespace:email.retainedBounce.namespace,noReplay:true,supportingOnly:true});return email;
}
